// 深度合并工具
function deepMerge(target: Messages, source: Messages): Messages {
  const output: Messages = { ...target }
  for (const key of Object.keys(source)) {
    if (
      source[key] &&
      typeof source[key] === 'object' &&
      !Array.isArray(source[key]) &&
      target[key] &&
      typeof target[key] === 'object' &&
      !Array.isArray(target[key])
    ) {
      output[key] = deepMerge(target[key], source[key])
    } else {
      output[key] = source[key]
    }
  }
  return output
}

export function extendMessages(locale: LocaleCode, base: Messages): Messages {
  const extMap: Record<LocaleCode, Messages> = {
    zh: zhExt,
    en: enExt,
    ja: jaExt,
    ko: koExt,
    es: esExt,
    fr: frExt,
    ar: arExt,
    id: idExt,
    ms: msExt,
    vi: viExt,
    th: thExt,
    fil: filExt,
  }
  return deepMerge(base, extMap[locale])
}
